{
  "flashcards": [
    {
      "front": "Where does photosynthesis mainly take place in leaf cells?",
      "back": "In the chloroplasts, which contain the green pigment chlorophyll."
    },
    {
      "front": "What is the overall chemical equation for photosynthesis?",
      "back": "6CO2 + 6H2O + light energy -> C6H12O6 + 6O2."
    },
    {
      "front": "Where do the light-dependent reactions occur?",
      "back": "In the thylakoid membranes, where light splits water and produces ATP and NADPH."
    },
    {
      "front": "Where does the Calvin cycle take place?",
      "back": "In the stroma, where carbon dioxide is fixed by RuBisCO and converted into glucose."
    },
    {
      "front": "What three factors affect the rate of photosynthesis?",
      "back": "Light intensity, carbon dioxide concentration, and temperature."
    }
  ],
  "warnings": []
}
